+import * as Cloudflare from "alchemy/Cloudflare";
+import { Stack } from "alchemy/Stack";
+import * as Config from "effect/Config";
+import * as Effect from "effect/Effect";
+
+// Leenk's Alchemy stack. Two stages mirror the two named Environments:
+// `dev` is an isolated preview Worker on workers.dev, `prod` is the live
+// Worker behind www.yusoofsh.id. Physical names for existing resources are
+// pinned exactly so adoption never creates a second bucket or dataset.
+
+const isProd = (stack: Stack) => stack.stage === "prod";
+
+const StaticFiles = Cloudflare.R2.Bucket("StaticFiles", {
+  name: "leenk-static",
+});
+
+const ShortlinkAnalytics = Cloudflare.AnalyticsEngine.Dataset(
+  "ShortlinkAnalytics",
+  { dataset: "leenk_shortlinks_v2" },
+);
+
+const SiteAnalytics = Cloudflare.AnalyticsEngine.Dataset("SiteAnalytics", {
+  dataset: "leenk_site_events",
+});
+
+const Cms = Cloudflare.D1.Database(
+  "Cms",
+  Effect.gen(function* () {
+    const stack = yield* Stack;
+    return {
+      name: isProd(stack) ? "leenk-cms" : "leenk-cms-dev",
+      primaryLocationHint: "apac" as const,
+      migrationsDir: "./d1/migrations",
+    };
+  }),
+);
+
+const OwnerPolicy = Cloudflare.Access.Policy("OwnerPolicy", {
+  name: "Allow Owner",
+  decision: "allow",
+  include: [{ email: { email: "f6sjdd6d6f@privaterelay.appleid.com" } }],
+});
+
+// Production-only owner boundaries for the dashboard and its API. The dev
+// stage is covered by the existing "leenk - preview" Access application on
+// *-leenk.yusoofsh.workers.dev.
+const DashboardApp = Cloudflare.Access.Application("DashboardApp", {
+  type: "self_hosted",
+  name: "leenk - dashboard",
+  domain: "www.yusoofsh.id/dashboard",
+  policies: [OwnerPolicy.policyId],
+});
+
+const DashboardApiApp = Cloudflare.Access.Application("DashboardApiApp", {
+  type: "self_hosted",
+  name: "leenk - dashboard api",
+  domain: "www.yusoofsh.id/api/dashboard",
+  policies: [OwnerPolicy.policyId],
+});
+
+export const Website = Cloudflare.Website.Astro(
+  "Website",
+  Effect.gen(function* () {
+    const stack = yield* Stack;
+    const prod = isProd(stack);
+    return {
+      // `dev-leenk` matches the existing `*-leenk.yusoofsh.workers.dev`
+      // Access pattern; `leenk` is the live Worker name to adopt in prod.
+      name: prod ? "leenk" : "dev-leenk",
+      domain: prod ? "www.yusoofsh.id" : null,
+      astro: {
+        site: "https://www.yusoofsh.id/",
+        output: "server" as const,
+      },
+      env: {
+        STATIC_FILES: StaticFiles,
+        SHORTLINK_ANALYTICS: ShortlinkAnalytics,
+        SITE_ANALYTICS: SiteAnalytics,
+        CMS: Cms,
+        STATIC_UPLOAD_TOKEN: Config.redacted("STATIC_UPLOAD_TOKEN"),
+        CLOUDFLARE_ACCOUNT_ID: Config.string("CLOUDFLARE_ACCOUNT_ID").pipe(
+          Config.withDefault(""),
+        ),
+        CLOUDFLARE_ANALYTICS_TOKEN: Config.option(
+          Config.redacted("CLOUDFLARE_ANALYTICS_TOKEN"),
+        ),
+      },
+    };
+  }),
+);
+
+export type WebsiteEnv = Cloudflare.InferEnv<typeof Website>;
+
+export default Alchemy.Stack(
+  "Leenk",
+  {
+    providers: Cloudflare.providers(),
+    state: Cloudflare.state(),
+  },
+  Effect.gen(function* () {
+    const stack = yield* Stack;
+    const website = yield* Website;
+    const outputs: Record<string, unknown> = { url: website.url };
+    if (isProd(stack)) {
+      const dashboard = yield* DashboardApp;
+      const dashboardApi = yield* DashboardApiApp;
+      outputs.dashboard = dashboard.url;
+      outputs.dashboardApi = dashboardApi.url;
+    }
+    return outputs;
+  }),
+);
