async function deleteShortlink(
  request: Request,
  code: string,
  storage: ShortlinkStorage,
  uploadToken: string | undefined,
  siteAnalytics: SiteAnalytics | undefined,
): Promise<Response> {
  const authError = await authorizeMutation(
    request,
    uploadToken,
    "SHORTLINKS_NOT_CONFIGURED",
    "Shortlink writes are not configured",
  );
  if (authError) return authError;
  if (!isValidShortlinkCode(code)) return shortlinkNotFound();

  let record: ShortlinkRecord | null = null;
  try {
    record = await storage.get(code);
  } catch (error) {
    console.error(
      JSON.stringify({
        error: error instanceof Error ? error.message : "Unknown error",
        event: "shortlink_label_lookup_failed",
        message: "shortlink label lookup failed before delete",
      }),
    );
  }
  await storage.delete(code);
  if (siteAnalytics) {
    recordSiteAnalyticsEvent(
      request,
      {
        event: "shortlink_deleted",
        ...(record ? { label: shortlinkLabel(record) } : {}),
      },
      siteAnalytics,
    );
  }
  return new Response(null, {
    status: 204,
    headers: { "Cache-Control": "no-store" },
  });
}

